// Writes content/agent-reference.json: for every library item in
// registry.json, what an AI agent needs to use it without seeing its code:
// what it is, how to install and import it, its props (read from the
// component's TypeScript, with each prop's own doc comment and default) and
// the types those props use. lib/agent-reference.ts turns it into the
// "Install / Usage / Props" part of each docs page's Markdown (the .md URL,
// Accept: text/markdown, llms-full.txt).
//
// Run by scripts/build-registry.mjs after a successful build, so it's
// regenerated by `pnpm registry:build` and by every `pnpm build` (deploys).
// Items with no description, or whose props can't be found, are listed as
// warnings: the reference is only as good as the source comments.

import { writeFileSync } from "node:fs";
import path from "node:path";

import { Node, Project, SyntaxKind } from "ts-morph";

const OUTPUT = "content/agent-reference.json";
/** Longest default value shown as-is; longer ones are cut. */
const DEFAULT_MAX = 80;

const project = new Project({
  compilerOptions: { allowJs: false, jsx: 4 },
  skipAddingFilesFromTsConfig: true,
});

const docOf = (node) =>
  Node.isJSDocable(node)
    ? node
        .getJsDocs()
        .map((doc) => doc.getDescription().trim())
        .filter(Boolean)
        .join(" ")
        .replaceAll(/\s+/g, " ")
    : "";

const shorten = (raw) => {
  const text = raw.replaceAll(/\s+/g, " ");
  return text.length > DEFAULT_MAX
    ? `${text.slice(0, DEFAULT_MAX - 1)}…`
    : text;
};

/**
 * A default from the component's parameter list, readable: literals as
 * written, a same-file constant resolved to its literal, anything bigger
 * (arrays, objects) described rather than dumped.
 */
const describeDefault = (initializer, file) => {
  if (!initializer) {
    return null;
  }
  let node = initializer;
  if (Node.isIdentifier(node)) {
    const declared = file.getVariableDeclaration(node.getText());
    const value = declared?.getInitializer();
    if (!value) {
      return node.getText();
    }
    node = value;
  }
  if (Node.isAsExpression(node) || Node.isSatisfiesExpression(node)) {
    node = node.getExpression();
  }
  if (
    Node.isStringLiteral(node) ||
    Node.isNoSubstitutionTemplateLiteral(node)
  ) {
    return shorten(JSON.stringify(node.getLiteralValue()));
  }
  if (
    Node.isNumericLiteral(node) ||
    node.getKind() === SyntaxKind.TrueKeyword ||
    node.getKind() === SyntaxKind.FalseKeyword ||
    node.getKind() === SyntaxKind.NullKeyword
  ) {
    return node.getText();
  }
  if (Node.isArrayLiteralExpression(node) || Node.isCallExpression(node)) {
    return "built-in demo content";
  }
  if (Node.isObjectLiteralExpression(node)) {
    return "built-in demo value";
  }
  return shorten(node.getText());
};

/** Members of an interface or object type, as prop rows. */
const membersOf = (declaration) => {
  const members = Node.isInterfaceDeclaration(declaration)
    ? declaration.getProperties()
    : (declaration
        .getTypeNode()
        ?.asKind(SyntaxKind.TypeLiteral)
        ?.getProperties() ?? []);
  return members.map((member) => ({
    description: docOf(member),
    name: member.getName(),
    optional: member.hasQuestionToken(),
    type: member.getTypeNode()?.getText().replaceAll(/\s+/g, " ") ?? "unknown",
  }));
};

/** Every exported interface or type alias in the item's files, by name. */
const exportedTypes = (files) => {
  const types = new Map();
  for (const file of files) {
    for (const declaration of [
      ...file.getInterfaces(),
      ...file.getTypeAliases(),
    ]) {
      if (declaration.isExported()) {
        types.set(declaration.getName(), declaration);
      }
    }
  }
  return types;
};

/** The function component a file exports by default (or its first exported one). */
const findComponent = (file) => {
  const defaultExport = file.getDefaultExportSymbol();
  const declaration =
    defaultExport?.getAliasedSymbol()?.getDeclarations()[0] ??
    defaultExport?.getDeclarations()[0];
  if (declaration && Node.isExportAssignment(declaration)) {
    const name = declaration.getExpression().getText();
    const found = file.getVariableDeclaration(name) ?? file.getFunction(name);
    if (found) {
      return found;
    }
  } else if (declaration) {
    return declaration;
  }
  return file
    .getVariableDeclarations()
    .find((v) => v.isExported() && /^[A-Z]/.test(v.getName()));
};

/** The defaults in a component's destructured props parameter, by prop. */
const readDefaults = (parameter, file) => {
  const defaults = new Map();
  const binding = parameter?.getNameNode();
  if (binding && Node.isObjectBindingPattern(binding)) {
    for (const element of binding.getElements()) {
      const key = element.getPropertyNameNode()?.getText() ?? element.getName();
      defaults.set(key, describeDefault(element.getInitializer(), file));
    }
  }
  return defaults;
};

/** The item's main component: its name, props type and defaults. */
const readComponent = (file) => {
  const component = findComponent(file);
  if (!component) {
    return null;
  }
  const fn = Node.isVariableDeclaration(component)
    ? (component.getInitializerIfKind(SyntaxKind.ArrowFunction) ??
      component.getInitializerIfKind(SyntaxKind.FunctionExpression))
    : component;
  const parameter = fn?.getParameters?.()[0];
  return {
    defaults: readDefaults(parameter, file),
    name: component.getName(),
    propsType: parameter?.getTypeNode()?.getText(),
  };
};

/** "Omit<ComponentProps<"section">, "children">" → the element it extends. */
const extendedElement = (declaration) => {
  if (!declaration || !Node.isInterfaceDeclaration(declaration)) {
    return null;
  }
  const heritage = declaration
    .getExtends()
    .map((clause) => clause.getText())
    .join(" ");
  return /ComponentProps<\s*"(\w+)"\s*>/.exec(heritage)?.[1] ?? null;
};

/** What's missing from an item's reference, for the build to report. */
const gapsIn = (item, propsDeclaration, props) => [
  ...(propsDeclaration ? [] : [`${item.name}: couldn't find its props type`]),
  ...props
    .filter((prop) => !prop.description)
    .map((prop) => `${item.name}: prop "${prop.name}" has no doc comment`),
  ...(item.description
    ? []
    : [`${item.name}: no description in registry.json`]),
];

/** Fields of the types its props use that have no doc comment. */
const fieldGapsIn = (item, relatedTypes) =>
  relatedTypes.flatMap((type) =>
    type.fields
      .filter((field) => !field.description)
      .map(
        (field) =>
          `${item.name}: field "${type.name}.${field.name}" has no doc comment`
      )
  );

/** The types its props mention by name, documented alongside. */
const relatedTypesOf = (props, types, propsType) => {
  const mentioned = new Set(
    props.flatMap((prop) => prop.type.match(/\b[A-Z]\w+\b/g) ?? [])
  );
  return [...mentioned]
    .filter((name) => name !== propsType && types.has(name))
    .map((name) => ({ fields: membersOf(types.get(name)), name }))
    .filter((type) => type.fields.length > 0);
};

/** The browse page's tags (slugs, labelled in constants/taxonomy.ts) and who it's for. */
const browseOf = (item) => ({
  tags: {
    categories: item.categories ?? [],
    styles: item.meta?.styles ?? [],
    types: item.meta?.types ?? [],
  },
  useCases: item.meta?.useCases ?? [],
});

/** One item's reference, and what's missing from it. */
const describeItem = (item) => {
  const meta = item.meta ?? {};
  const entries = item.files ?? [];
  const files = entries.map((entry) =>
    project.addSourceFileAtPath(path.resolve(entry.path))
  );
  const [main] = files;
  const types = exportedTypes(files);
  const component = main ? readComponent(main) : null;
  const propsType = component?.propsType;
  const propsDeclaration = propsType
    ? (types.get(propsType) ??
      main.getInterface(propsType) ??
      main.getTypeAlias(propsType))
    : null;
  const props = propsDeclaration
    ? membersOf(propsDeclaration).map((prop) => ({
        ...prop,
        default: component.defaults.get(prop.name),
      }))
    : [];
  const mainTarget = entries[0]?.target ?? "";
  const relatedTypes = relatedTypesOf(props, types, propsType);

  return {
    gaps: [
      ...gapsIn(item, propsDeclaration, props),
      ...fieldGapsIn(item, relatedTypes),
    ],
    reference: {
      component: component?.name ?? null,
      dependencies: item.dependencies ?? [],
      description: item.description ?? "",
      docs: `/docs/${meta.library}/${meta.docs ?? item.name}`,
      extends: extendedElement(propsDeclaration),
      files: entries.map((entry) => entry.target ?? entry.path),
      id: meta.id ?? null,
      import: mainTarget
        ? `@/${mainTarget.replace(/\.(tsx?|jsx?)$/, "")}`
        : null,
      library: meta.library,
      name: item.name,
      paid: meta.free !== true,
      props,
      registryDependencies: item.registryDependencies ?? [],
      title: item.title,
      types: relatedTypes,
      ...browseOf(item),
    },
  };
};

export const writeAgentReference = (registry) => {
  const reference = {};
  const warnings = [];
  for (const item of registry.items) {
    if (item.meta?.library) {
      const described = describeItem(item);
      reference[item.name] = described.reference;
      warnings.push(...described.gaps);
    }
  }

  writeFileSync(OUTPUT, `${JSON.stringify(reference, null, 2)}\n`);
  console.log(
    `Agent reference: ${Object.keys(reference).length} item(s) → ${OUTPUT}`
  );
  for (const warning of warnings) {
    console.warn(`  ! ${warning}`);
  }
};
